        {
            *(b->pbuffer ++) = '.';
            *(b->pbuffer ++) = '.';
            *(b->pbuffer ++) = '.';
        }
        else
        {
            *(b->pbuffer ++) = mini_pchar_decode(s[i]);
        }
    }
    *(b->pbuffer) = 0;
