mini_vpprintf.body:
char bf[24];
    char bf2[24];
    char ch;
    s32 n;
    n = 0;
    while ((ch=*(fmt++)))
    {
        s32 len;
        if (ch != '%')
        {
            len = 1;
            len = _putsAscii(&ch, len, buf);
        }
        else
        {
            char pad_char = ' ';
            s32 pad_to = 0;
            char l = 0;
            char *ptr;

            ch=*(fmt++);


            if (ch == '0')
                pad_char = '0';
            while (ch >= '0' && ch <= '9')
            {
                pad_to = pad_to * 10 + (ch - '0');
                ch= *(fmt++);
            }
            if(pad_to > (s32) sizeof(bf))
            {
                pad_to = sizeof(bf);
            }
            if (ch == 'l')
            {
                l = 1;
                ch=*(fmt++);
            }

            switch (ch)
            {
                case 0:
                    goto end;
                case 'u':
                case 'd':
                    if(l)
                    {
                        len = mini_itoa(va_arg(va, u32), 10, 0, (ch=='u'), bf2);
                    }
                    else
                    {
                        if(ch == 'u')
                        {
                            len = mini_itoa((u32) va_arg(va, u32), 10, 0, 1, bf2);
                        }
                        else
                        {
                            len = mini_itoa((s32) va_arg(va, s32), 10, 0, 0, bf2);
                        }
                    }
                    len = mini_pad(bf2, len, pad_char, pad_to, bf);
                    len = _putsAscii(bf, len, buf);
                    break;

                case 'x':
                case 'X':
                    if(l)
                    {
                        len = mini_itoa(va_arg(va, u32), 16, (ch=='X'), 1, bf2);
                    }
                    else
                    {
                        len = mini_itoa((u32) va_arg(va, u32), 16, (ch=='X'), 1, bf2);
                    }
                    len = mini_pad(bf2, len, pad_char, pad_to, bf);
                    len = _putsAscii(bf, len, buf);
                    break;
                case 'b':
                    len = mini_itoa_bin(va_arg(va, u32), bf2);
                    len = mini_pad(bf2, len, pad_char, pad_to, bf);
                    len = _putsAscii(bf, len, buf);
                    break;
                case 'c' :
                    ch = (char)(va_arg(va, s32));
                    len = mini_pad(&ch, 1, pad_char, pad_to, bf);
                    len = _putsAscii(bf, len, buf);
                    break;

                case 's' :
                    ptr = va_arg(va, char*);
                    len = mini_strlen(ptr);
                    if (pad_to > 0)
                    {
                        len = mini_pad(ptr, len, pad_char, pad_to, bf);
                        len = _putsAscii(bf, len, buf);
                    }
                    else
                    {
                        len = _putsAscii(ptr, len, buf);
                    }
                    break;
                case 'S' :  
                    ptr = va_arg(va, char*);
                    len = StringLength((u8*)ptr);
                    if (pad_to > 0)
                    {
                        len = mini_pad(ptr, len, pad_char, pad_to, bf);
                        len = _putsEncoded(bf, len, buf);
                    }
                    else
                    {
                        len = _putsEncoded(ptr, len, buf);
                    }
                    break;
                default:
                    len = 1;
                    len = _putsAscii(&ch, len, buf);
                    break;
            }
        }
        n = n + len;
    }
end:
    return n;
